<?php
require __DIR__.'/includes/bootstrap.php';require_auth();require __DIR__.'/includes/layout.php';require __DIR__.'/includes/data.php';
$monthStart=date('Y-m-01');$todayDate=date('Y-m-d');
$q=$pdo->prepare('SELECT COALESCE(SUM(total_amount),0) total,COALESCE(SUM(cash_amount),0) cash,COALESCE(SUM(card_amount),0) card,COALESCE(SUM(talabat_amount+keeta_amount+snoonu_amount),0) apps,COUNT(*) records FROM sales WHERE sale_date BETWEEN ? AND ? AND status="completed" AND deleted_at IS NULL');$q->execute([$monthStart,$todayDate]);$monthSales=$q->fetch();
$products=$pdo->query('SELECT p.id,p.name,u.symbol,p.minimum_stock,COALESCE(SUM(it.quantity_in-it.quantity_out),0) available FROM products p JOIN units u ON u.id=p.unit_id LEFT JOIN inventory_transactions it ON it.product_id=p.id WHERE p.deleted_at IS NULL AND p.status="active" GROUP BY p.id,p.name,u.symbol,p.minimum_stock ORDER BY p.name')->fetchAll();$low=array_values(array_filter($products,fn($p)=>(float)$p['available']<=(float)$p['minimum_stock']));usort($low,fn($a,$b)=>(float)$a['available']<=>(float)$b['available']);
$sales=$pdo->query('SELECT s.*,b.name branch,br.name brand FROM sales s JOIN branches b ON b.id=s.branch_id JOIN brands br ON br.id=s.brand_id WHERE s.deleted_at IS NULL ORDER BY s.sale_date DESC,s.id DESC LIMIT 7')->fetchAll();
$recent=$pdo->query('SELECT it.transaction_type,it.reference_no,it.quantity_in,it.quantity_out,it.created_at,p.name product,u.symbol,b.name branch FROM inventory_transactions it JOIN products p ON p.id=it.product_id JOIN units u ON u.id=p.unit_id JOIN branches b ON b.id=it.branch_id ORDER BY it.id DESC LIMIT 7')->fetchAll();
render_header('Dashboard','dashboard');
?><div class="page-head"><div><span class="eyebrow">MONTH-TO-DATE BUSINESS</span><h1>Good <?=date('H')<12?'morning':(date('H')<17?'afternoon':'evening')?>, <?=e(explode(' ',user()['name'])[0])?></h1><p><?=date('l, j F Y')?> · Sales from <?=date('j M',strtotime($monthStart))?> to today and current raw-item stock</p></div><div class="page-head-actions"><a class="btn" href="<?=app_url('monthly-sales.php')?>"><i data-icon="chart"></i>Monthly History</a><a class="btn primary" href="<?=app_url('sales.php?action=create')?>"><i data-icon="plus"></i>Add Daily Sales</a></div></div>
<div class="grid stats"><article class="stat" style="--accent:#6d5dfc"><div class="stat-head"><span>TOTAL SALES THIS MONTH</span><span class="stat-icon"><i data-icon="receipt"></i></span></div><strong><?=money($monthSales['total'])?></strong><span class="trend"><?=number_format($monthSales['records'])?> completed closing entries · <?=date('j M',strtotime($monthStart))?>–<?=date('j M')?></span></article><article class="stat" style="--accent:#17b783"><div class="stat-head"><span>CASH THIS MONTH</span><span class="stat-icon"><i data-icon="cash"></i></span></div><strong><?=money($monthSales['cash'])?></strong><span class="trend up">Completed cash sales</span></article><article class="stat" style="--accent:#2f80ed"><div class="stat-head"><span>CARD THIS MONTH</span><span class="stat-icon"><i data-icon="card"></i></span></div><strong><?=money($monthSales['card'])?></strong><span class="trend">Completed card sales</span></article><article class="stat" style="--accent:#ef476f"><div class="stat-head"><span>DELIVERY APPS THIS MONTH</span><span class="stat-icon"><i data-icon="truck"></i></span></div><strong><?=money($monthSales['apps'])?></strong><span class="trend">Talabat + Keeta + Snoonu</span></article></div>
<div class="dashboard-actions"><a class="dashboard-action primary-action" href="<?=app_url('sales.php?action=create')?>"><span><i data-icon="receipt"></i></span><div><b>End-of-Day Sales</b><small>Cash, Card, Talabat, Keeta, Snoonu</small></div><em>→</em></a><a class="dashboard-action" href="<?=app_url('receiving.php?action=create')?>"><span><i data-icon="inbox"></i></span><div><b>Receive Raw Item</b><small>Branch, brand, quantity and unit cost</small></div><em>→</em></a><a class="dashboard-action" href="<?=app_url('products.php?action=create')?>"><span><i data-icon="plus"></i></span><div><b>Add Raw Item</b><small>Name and unit only</small></div><em>→</em></a></div>
<div class="inventory-kpis dashboard-stock-kpis"><div><span>Raw items</span><b><?=count($products)?></b></div><div><span>Low / empty</span><b><?=count($low)?></b></div><div><span>Stock tracking</span><b>Automatic</b></div></div>
<div class="grid layout-2"><article class="card"><div class="card-head"><div><h2>Recent daily sales</h2><small>Latest closing summaries</small></div><a href="<?=app_url('sales.php')?>">View by date →</a></div><div class="activity-list"><?php foreach($sales as $row):?><div class="activity"><span class="activity-icon"><i data-icon="receipt"></i></span><div><b><?=e($row['branch'])?> · <?=e($row['brand'])?></b><small><?=date('d M Y',strtotime($row['sale_date']))?> · Cash <?=money($row['cash_amount'])?> · Card <?=money($row['card_amount'])?></small></div><span class="amount"><?=money($row['total_amount'])?></span></div><?php endforeach;?><?php if(!$sales):?><div class="empty"><div class="empty-icon"><i data-icon="receipt"></i></div>No daily sales entered yet.</div><?php endif;?></div></article><article class="card"><div class="card-head"><div><h2>Low / empty raw items</h2><small>Items requiring attention</small></div><span class="status pending"><?=count($low)?> items</span></div><div class="activity-list"><?php foreach(array_slice($low,0,7) as $item):?><div class="activity"><span class="activity-icon" style="color:var(--warning)">!</span><div><b><?=e($item['name'])?></b><small>Current available quantity</small></div><span class="amount"><?=number_format($item['available'],3).' '.e($item['symbol'])?></span></div><?php endforeach;?><?php if(!$low):?><div class="empty">All raw items have available stock.</div><?php endif;?></div></article></div>
<article class="card" style="margin-top:20px"><div class="card-head"><div><h2>Recent stock activity</h2><small>Received stock, wastage and adjustments</small></div><a href="<?=app_url('inventory.php')?>">View stock →</a></div><div class="activity-list"><?php foreach($recent as $row):?><div class="activity"><span class="activity-icon"><i data-icon="swap"></i></span><div><b><?=e($row['product'])?></b><small><?=e(ucwords(str_replace('_',' ',$row['transaction_type'])))?> · <?=e($row['branch'])?> · <?=e($row['reference_no'])?></small></div><span class="amount"><?=($row['quantity_in']>0?'+':'−').number_format($row['quantity_in']?:$row['quantity_out'],3).' '.e($row['symbol'])?></span></div><?php endforeach;?><?php if(!$recent):?><div class="empty">Add a raw item and receive stock to begin.</div><?php endif;?></div></article><?php render_footer('dashboard');
